#ifndef CPP_FUNDAMENTALS_SOBRES_H
#define CPP_FUNDAMENTALS_SOBRES_H

#include <string>

// Dominio de ambas funciones: 0 <= tarjetas <= 120.
// Cada sobre admite hasta 12 tarjetas.
int sobres_necesarios(int tarjetas);
std::string descripcion_sobres(int tarjetas);

#endif

// Archivo: sobres.cpp
#include "sobres.h"

int sobres_necesarios(int tarjetas) {
    int completos = tarjetas / 12;
    if (tarjetas % 12 != 0) {
        ++completos;
    }
    return completos;
}

std::string descripcion_sobres(int tarjetas) {
    const int cantidad = sobres_necesarios(tarjetas);
    if (cantidad == 0) {
        return "Sin tarjetas";
    }
    if (cantidad == 1) {
        return "Un sobre";
    }
    return "Varios sobres";
}

// Archivo: main.cpp
#include "sobres.h"
#include <iostream>

int main() {
    const int tarjetas = 25;
    std::cout << descripcion_sobres(tarjetas) << ": "
        << sobres_necesarios(tarjetas);
    return 0;
}

